#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long MOD = 1000000007;
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    // dp[j]: plans for the prefix whose last stamp is j.
    array<long long, 5> dp;
    dp.fill(1);
    for (int t = 1; t < n; t++) {
        long long x = a[t - 1], y = a[t];
        array<long long, 5> nxt{};
        for (int j = 0; j < 5; j++)
            for (int i = 0; i < 5; i++) {
                bool ok = y > x ? j > i : y < x ? j < i : j != i;
                if (ok) nxt[j] = (nxt[j] + dp[i]) % MOD;
            }
        dp = nxt;
    }
    long long total = 0;
    for (long long v : dp) total += v;
