import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 1000000007L;
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // dp[j]: plans for the prefix whose last stamp is j.
        long[] dp = {1, 1, 1, 1, 1};
        for (int t = 1; t < n; t++) {
            long x = a[t - 1], y = a[t];
            long[] nxt = new long[5];
            for (int j = 0; j < 5; j++)
                for (int i = 0; i < 5; i++) {
                    boolean ok = y > x ? j > i : y < x ? j < i : j != i;
                    if (ok) nxt[j] = (nxt[j] + dp[i]) % MOD;
                }
            dp = nxt;
        }
        long total = 0;
        for (long v : dp) total += v;
        System.out.println(total % MOD);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	const mod = 1000000007
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// dp[j]: plans for the prefix whose last stamp is j.
	dp := [5]int64{1, 1, 1, 1, 1}
	for t := 1; t < n; t++ {
		x, y := a[t-1], a[t]
		var nxt [5]int64
		for j := 0; j < 5; j++ {
			for i := 0; i < 5; i++ {
				ok := j != i
				if y > x {
					ok = j > i
				} else if y < x {
					ok = j < i
				}
				if ok {
					nxt[j] = (nxt[j] + dp[i]) % mod
				}
			}
		}
		dp = nxt
	}
	var total int64
	for _, v := range dp {
		total += v
	}
	fmt.Println(total % mod)
}
